INSERT INTO setting (id, type, value, note) VALUES ('utility.teleport.warmup-seconds', 'int', '3', 'Seconds the player must stand still before any teleport happens (0 disables the warm-up). Players with vampyuyu.sb.utility.bypass.warmup skip it.');
INSERT INTO setting (id, type, value, note) VALUES ('utility.teleport.move-tolerance', 'real', '0.6', 'Moving more than this many blocks from the start spot cancels the teleport.');
INSERT INTO setting (id, type, value, note) VALUES ('utility.teleport.cancel-on-damage', 'bool', 'true', 'Taking damage cancels the teleport.');
INSERT INTO setting (id, type, value, note) VALUES ('utility.teleport.show-title', 'bool', 'true', 'Show a title countdown during the warm-up (chat only when false).');
INSERT INTO setting (id, type, value, note) VALUES ('utility.combat.enabled', 'bool', 'true', 'Teleports are refused for a while after being hit. vampyuyu.sb.utility.bypass.combat ignores it.');
INSERT INTO setting (id, type, value, note) VALUES ('utility.combat.tag-seconds', 'int', '10', '');
INSERT INTO setting (id, type, value, note) VALUES ('utility.combat.include-mobs', 'bool', 'false', 'Also tag when the damage comes from a mob. Off by default: only player-versus-player fights tag, so a creeper never blocks /spawn or /home as an escape.');
INSERT INTO setting (id, type, value, note) VALUES ('utility.combat.notify', 'bool', 'true', 'Tell the player in chat when the tag starts and when it ends (the action bar belongs to the items feature).');
INSERT INTO setting (id, type, value, note) VALUES ('utility.homes.default-limit', 'int', '3', 'Homes a player gets without a vampyuyu.sb.utility.homes.<n> permission.');
INSERT INTO setting (id, type, value, note) VALUES ('utility.homes.max-limit', 'int', '100', 'Upper bound of what a permission node can grant; vampyuyu.sb.utility.homes.unlimited grants exactly this.');
INSERT INTO setting (id, type, value, note) VALUES ('utility.homes.max-name-length', 'int', '16', '');
INSERT INTO setting (id, type, value, note) VALUES ('utility.homes.default-name', 'text', 'home', 'Name used by /home and /sethome without an argument.');
INSERT INTO setting (id, type, value, note) VALUES ('utility.tpa.expire-seconds', 'int', '60', '');
INSERT INTO setting (id, type, value, note) VALUES ('utility.tpa.send-cooldown-seconds', 'int', '10', 'Seconds a player must wait between two requests they send (stops spam).');
INSERT INTO setting (id, type, value, note) VALUES ('utility.tpa.max-pending-per-target', 'int', '5', 'Open requests one player can have waiting for an answer.');
INSERT INTO setting (id, type, value, note) VALUES ('utility.tpa.teleport-cooldown-seconds', 'int', '5', 'Seconds after a successful /tpa or /tpahere teleport before the same player may be teleported by one again.');
INSERT INTO setting (id, type, value, note) VALUES ('utility.spawn.world', 'text', '', 'World used by /spawn outside Skyblock worlds. Blank = the first loaded world.');
INSERT INTO setting (id, type, value, note) VALUES ('utility.rtp.enabled', 'bool', 'true', '');
INSERT INTO setting (id, type, value, note) VALUES ('utility.rtp.world', 'text', '', 'The vanilla survival world. Blank = the first loaded world. Players must be in it to use /rtp.');
INSERT INTO setting (id, type, value, note) VALUES ('utility.rtp.cooldown-seconds', 'int', '600', '');
INSERT INTO setting (id, type, value, note) VALUES ('utility.rtp.min-radius', 'int', '200', '');
INSERT INTO setting (id, type, value, note) VALUES ('utility.rtp.max-radius', 'int', '5000', '');
INSERT INTO setting (id, type, value, note) VALUES ('utility.rtp.use-world-spawn', 'bool', 'true', 'Centre of the search area; use-world-spawn true centres it on the world spawn instead.');
INSERT INTO setting (id, type, value, note) VALUES ('utility.rtp.center-x', 'int', '0', '');
INSERT INTO setting (id, type, value, note) VALUES ('utility.rtp.center-z', 'int', '0', '');
INSERT INTO setting (id, type, value, note) VALUES ('utility.rtp.max-attempts', 'int', '12', 'Random points tried before giving up (the cooldown is not used when nothing was found).');
INSERT INTO setting (id, type, value, note) VALUES ('utility.rtp.search-timeout-seconds', 'int', '20', 'Seconds before an unfinished search is abandoned.');
INSERT INTO setting (id, type, value, note) VALUES ('utility.sit.seat-height', 'real', '0.6', 'Interaction entity height; the player''s feet end up at (floor + seat-offset) + seat-height - 0.6.');
INSERT INTO setting (id, type, value, note) VALUES ('utility.sit.seat-offset', 'real', '-0.2', 'Vertical offset of the seat from the floor, tune it if the player floats or sinks.');
INSERT INTO setting (id, type, value, note) VALUES ('utility.trash.keep-ids', 'list', '', 'Items with these custom ids are handed back on close instead of being destroyed.');
